#include <WiFi.h>
#include "esp_wifi.h"

// Заглушка, чтобы Arduino-ядро разрешило отправку сырых кадров
extern "C" int ieee80211_raw_frame_sanity_check(int32_t arg, int32_t arg2, int32_t arg3) {
  return 1;
}

const char* NETWORKS[10] = {
  "Бесплатный Wi-Fi",
  "Калюжный",
  "Гуленко",
  "Григорьянц",
  "Чуканов",
  "Белокопытов",
  "Ткаченко",
  "Четыржоков",
  "Балакин",
  "Огурцов"
};

const uint8_t CHANNEL = 1;   // 1–13, все сети на одном канале

uint8_t packet[128];
uint16_t seq = 0;

// случайный MAC-адрес для каждой сети
void randomMac(int offset) {
  for (int i = 0; i < 6; i++) {
    packet[10 + offset * 6 + i] = random(0, 256);
  }
}

void sendBeacon(const char* ssid) {
  uint8_t len = strlen(ssid);

  // MAC-заголовок
  packet[0] = 0x80;                       // кадр типа beacon
  packet[1] = 0x00;
  packet[2] = 0x00; packet[3] = 0x00;     // duration
  packet[4] = packet[5] = packet[6] =     // адресат: broadcast
  packet[7] = packet[8] = packet[9] = 0xff;
  randomMac(0);                           // источник
  randomMac(1);                           // BSSID
  packet[22] = seq & 0xff;                // номер кадра
  packet[23] = (seq >> 8) & 0xff;         // (младшие 12 бит)
  seq++;

  // фиксированные поля
  packet[24] = 0x83; packet[25] = 0x51;   // timestamp
  packet[26] = 0xf7; packet[27] = 0x8f;
  packet[28] = 0x0f; packet[29] = 0x00;
  packet[30] = 0x00; packet[31] = 0x00;
  packet[32] = 0x64; packet[33] = 0x00;   // интервал маячков
  packet[34] = 0x31; packet[35] = 0x04;   // capability

  // имя сети
  packet[36] = 0x00;                      // тег SSID
  packet[37] = len;
  memcpy(&packet[38], ssid, len);

  // поддерживаемые скорости
  int i = 38 + len;
  packet[i++] = 0x01; packet[i++] = 0x08;
  packet[i++] = 0x82; packet[i++] = 0x84;
  packet[i++] = 0x8b; packet[i++] = 0x96;
  packet[i++] = 0x24; packet[i++] = 0x30;
  packet[i++] = 0x48; packet[i++] = 0x6c;

  // канал
  packet[i++] = 0x03; packet[i++] = 0x01;
  packet[i++] = CHANNEL;

  esp_wifi_80211_tx(WIFI_IF_STA, packet, i, false);
}

void setup() {
  Serial.begin(115200);

  WiFi.mode(WIFI_STA);
  WiFi.disconnect();
  delay(100);

  randomSeed(esp_random());

  // режим монитора — разрешает отправку сырых кадров
  esp_wifi_set_promiscuous(true);
  esp_wifi_set_channel(CHANNEL, WIFI_SECOND_CHAN_NONE);

  Serial.println("Рассылаю маячки...");
}

void loop() {
  for (int n = 0; n < 10; n++) {
    sendBeacon(NETWORKS[n]);
    delay(10);
  }
}

